import java.util.concurrent.*;

public class ProductionExecutorExample {
    public static void main(String[] args) {
        // Define a custom ThreadPoolExecutor to avoid unbounded pitfalls of Executors factory methods
        ExecutorService executor = new ThreadPoolExecutor(
            4, 
            8, 
            60L, 
            TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(100),
            Executors.defaultThreadFactory(),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        Callable<String> task = () -> {
            TimeUnit.MILLISECONDS.sleep(500);
            return "Task executed by: " + Thread.currentThread().getName();
        };

        Future<String> future = executor.submit(task);

        try {
            // Retrieve result with a strict timeout to prevent indefinite blocking
            String result = future.get(2, TimeUnit.SECONDS);
            System.out.println(result);
        } catch (TimeoutException | InterruptedException | ExecutionException e) {
            future.cancel(true);
            System.err.println("Task failed or timed out: " + e.getMessage());
        } finally {
            executor.shutdown();
        }
    }
}
